def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    import re

    # Regular expressions for the 4 supported statement forms
    patterns = [
        re.compile(r'^(?P<subject>\w+)\s+is\s+guilty\.$', re.IGNORECASE),
        re.compile(r'^(?P<subject>\w+)\s+is\s+not guilty\.$', re.IGNORECASE),
        re.compile(r'^I\s+am\s+guilty\.$', re.IGNORECASE),
        re.compile(r'^I\s+am\s+not guilty\.$', re.IGNORECASE)
    ]

    # Helper to determine if a statement references a weekday
    day_lower = {day.lower() for day in days_of_week}
    def contains_weekday(statement: str) -> bool:
        lowered = statement.lower()
        return any(day in lowered for day in day_lower)

    for speaker, stmts in statements.items():
        if not isinstance(stmts, list):
            continue  # skip malformed entries
        for stmt in stmts:
            if not isinstance(stmt, str):
                continue
            if contains_weekday(stmt):
                continue  # ignore statements about the day of the week
            stmt = stmt.strip()
            truth = None
            for pattern in patterns:
                match = pattern.match(stmt)
                if match:
                    if pattern.pattern == r'^(?P<subject>\w+)\s+is\s+guilty\.$':
                        subject = match.group('subject')
                    elif pattern.pattern == r'^(?P<subject>\w+)\s+is\s+not guilty\.$':
                        subject = match.group('subject')
                        subject = subject  # still subject string
                    elif pattern.pattern == r'^I\s+am\s+guilty\.$':
                        subject = speaker
                    elif pattern.pattern == r'^I\s+am\s+not guilty\.$':
                        subject = speaker
                    else:
                        continue  # should not happen

                    if pattern.pattern in [r'^(?P<subject>\w+)\s+is\s+guilty\.$', r'^I\s+am\s+guilty\.$']:
                        truth = (subject == scenario)
                    else:  # "is not guilty" or "I am not guilty"
                        truth = (subject != scenario)
                    break  # stop after first matching pattern

            if truth is None:
                # Statement does not match any supported pattern; ignore it
                continue

            # Verify truthfulness against liar status
            if speaker in liar_count:
                if truth:  # liars should be lying; truth must be False
                    return False
            else:
                if not truth:  # truth-tellers must say true statements
                    return False

    return True

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Helper to determine if a statement mentions a day of the week
    def is_day_statement(statement: str) -> bool:
        lowered = statement.lower()
        for day in days_of_week:
            if day.lower() in lowered:
                return True
        return False

    # Helper to determine truth value of a statement
    def statement_truth(statement: str, speaker: str) -> bool:
        # Identify subject
        lowered = statement.lower()
        if ' i ' in lowered or lowered.startswith('i ') or lowered.startswith('i am'):
            subject = speaker
        else:
            # look for pattern "something is" or "something am"
            if ' is ' in lowered:
                part = lowered.split(' is ', 1)[0]
                subject = part.strip().title()
            elif ' am ' in lowered:
                part = lowered.split(' am ', 1)[0]
                subject = part.strip().title()
            else:
                # cannot parse, assume statement non-guilt related; consider it true by default
                return True

        subject_not_guilty = 'not guilty' in lowered
        if subject == scenario:
            return not subject_not_guilty
        else:
            return subject_not_guilty

    # Evaluate all statements
    for speaker, stmts in statements.items():
        for stmt in stmts:
            if is_day_statement(stmt):
                continue  # skip day of week statements
            truth = statement_truth(stmt, speaker)
            if truth:
                if speaker in liar_count:
                    return False  # true statement from a liar
            else:
                if speaker not in liar_count:
                    return False  # false statement from a non-liar
    return True

